// Segment tracing keeps fast water droplets from passing through cover.
function boxHit(a,b,s){const c=Math.cos(s.rot||0),q=Math.sin(s.rot||0),dx=a.x-s.x,dz=a.z-s.z;const p=[dx*c-dz*q,a.y,dx*q+dz*c],v=[(b.x-a.x)*c-(b.z-a.z)*q,b.y-a.y,(b.x-a.x)*q+(b.z-a.z)*c];const w=s.type==='circle'?s.r*2:s.w,d=s.type==='circle'?s.r*2:s.d;const min=[-w/2,s.bottom||0,-d/2],max=[w/2,s.top,d/2];let lo=0,hi=1;for(let i=0;i<3;i++){if(Math.abs(v[i])<1e-9){if(p[i]<min[i]||p[i]>max[i])return null;}else{let u=(min[i]-p[i])/v[i],t=(max[i]-p[i])/v[i];if(u>t)[u,t]=[t,u];lo=Math.max(lo,u);hi=Math.min(hi,t);if(lo>hi)return null;}}return lo;}
export function traceWater(a,b,solids,targets=[],surfaces=[]){let best=Infinity,hit=null;const consider=(t,type,index=-1)=>{if(t!==null&&t>=0&&t<=1&&t<best){best=t;hit={type,index,t,x:a.x+(b.x-a.x)*t,y:a.y+(b.y-a.y)*t,z:a.z+(b.z-a.z)*t};}};
 for(const s of solids)consider(boxHit(a,b,s),'cover');
 for(const s of surfaces){if(!s.ramp)consider(boxHit(a,b,{...s,top:s.h+.28,bottom:s.h-.1}),'cover');else{const denom=(b.y-a.y)+(b.z-a.z)*s.h/s.d;if(Math.abs(denom)>1e-8){const t=(.28+(s.z+s.d/2-a.z)*s.h/s.d-a.y)/denom;const x=a.x+(b.x-a.x)*t,z=a.z+(b.z-a.z)*t;if(Math.abs(x-s.x)<=s.w/2&&Math.abs(z-s.z)<=s.d/2)consider(t,'cover');}}}
 for(let i=0;i<targets.length;i++){const s=targets[i],dx=b.x-a.x,dy=b.y-a.y,dz=b.z-a.z,ox=a.x-s.x,oy=a.y-s.y,oz=a.z-s.z,A=dx*dx+dy*dy+dz*dz,B=2*(ox*dx+oy*dy+oz*dz),C=ox*ox+oy*oy+oz*oz-s.r*s.r,D=B*B-4*A*C;if(A&&D>=0){const t=(-B-Math.sqrt(D))/(2*A);consider(C<=0?0:t,'target',i);}}
 if(a.y>=.28&&b.y<.28)consider((a.y-.28)/(a.y-b.y),'ground');return hit;
}
export class WaterTank{constructor(){this.water=100;this.cooldown=0;this.reload=0;}update(dt){this.cooldown=Math.max(0,this.cooldown-dt);if(this.reload>0){this.reload=Math.max(0,this.reload-dt);if(!this.reload)this.water=100;}}refill(){if(!this.reload&&this.water<100)this.reload=1.1;}fire(){if(this.reload||this.cooldown>0||this.water<1)return false;this.water--;this.cooldown=.075;return true;}}
